-- Mirrors the production migration generated by Supabase MCP.
-- No RLS policies or tenant permissions are changed.
alter table public.meals add column if not exists meal_time time(0) without time zone;
comment on column public.meals.meal_time is 'Local scheduled time in the camporee time_zone. NULL uses the application default for the meal type. Past-time display is derived, not a served flag.';
do $$ begin
  if not exists (select 1 from pg_constraint where conrelid='public.meals'::regclass and conname='meals_time_valid_minute') then
    alter table public.meals add constraint meals_time_valid_minute check (meal_time is null or (meal_time < time '24:00' and extract(second from meal_time)=0));
  end if;
end $$;
notify pgrst, 'reload schema';
